<script>
const selectAll=document.getElementById('selectAllQuestions'), boxes=[...document.querySelectorAll('.question-select')], deleteButton=document.getElementById('bulkDeleteButton'), count=document.getElementById('selectedCount');
function updateSelection(){const selected=boxes.filter(box=>box.checked).length;count.textContent=selected;deleteButton.disabled=selected===0;if(selectAll){selectAll.checked=boxes.length>0&&selected===boxes.length;selectAll.indeterminate=selected>0&&selected<boxes.length;}}
selectAll?.addEventListener('change',()=>{boxes.forEach(box=>box.checked=selectAll.checked);updateSelection()});boxes.forEach(box=>box.addEventListener('change',updateSelection));updateSelection();
</script>
